from __future__ import annotations

import json

from lfx.custom import Component
from lfx.io import MessageTextInput, Output
from lfx.schema.message import Message


class JudgmentSplitter(Component):
    display_name = "Judgment Splitter"
    description = (
        "Splits the relay-server input JSON {case_id, judgment, issue_catalog, scheme_catalog, catalog versions} "
        "into separate messages. Plain text input is treated as the judgment with empty catalogs."
    )
    icon = "Split"
    name = "JudgmentSplitter"

    inputs = [
        MessageTextInput(
            name="payload",
            display_name="Input JSON",
            info="JSON text from the relay server: {case_id, judgment, issue_catalog, issue_catalog_version, scheme_catalog, scheme_catalog_version}",
            required=True,
        ),
    ]

    outputs = [
        Output(display_name="Judgment", name="judgment", method="build_judgment", group_outputs=True),
        Output(display_name="Issue Catalog", name="issue_catalog", method="build_issue_catalog", group_outputs=True),
        Output(display_name="Scheme Catalog", name="scheme_catalog", method="build_scheme_catalog", group_outputs=True),
        Output(display_name="Catalog Versions", name="catalog_versions", method="build_catalog_versions", group_outputs=True),
        Output(display_name="Case ID", name="case_id", method="build_case_id", group_outputs=True),
    ]

    def _payload(self) -> dict:
        raw = getattr(self.payload, "text", None)
        text = str(raw if raw is not None else (self.payload or ""))
        stripped = text.strip()
        if stripped.startswith("{"):
            try:
                # Langflow 가 tweak 값의 \n 이스케이프를 실제 줄바꿈으로 바꿔 전달하는 경우가 있어 문자열 안의 제어 문자를 허용한다.
                value = json.loads(stripped, strict=False)
            except ValueError:
                value = None
            if isinstance(value, dict) and isinstance(value.get("judgment"), str):
                return value
        return {"case_id": "", "judgment": text, "issue_catalog": [], "scheme_catalog": []}

    def build_judgment(self) -> Message:
        # 원문 문자·공백·줄바꿈을 그대로 전달한다 (근거 인용 매칭 정확도).
        return Message(text=self._payload().get("judgment") or "")

    def build_issue_catalog(self) -> Message:
        items = self._payload().get("issue_catalog") or []
        lines = []
        for item in items if isinstance(items, list) else []:
            if not isinstance(item, dict) or not item.get("issueId"):
                continue
            lines.append(
                json.dumps(
                    {
                        "issue_id": str(item.get("issueId")),
                        "category": str(item.get("categoryName") or ""),
                        "label": str(item.get("label") or ""),
                        "criteria": str(item.get("criteria") or ""),
                    },
                    ensure_ascii=False,
                )
            )
        self.status = f"{len(lines)} catalog issues"
        return Message(text="\n".join(lines))

    def build_scheme_catalog(self) -> Message:
        items = self._payload().get("scheme_catalog") or []
        lines = [json.dumps(item, ensure_ascii=False) for item in items if isinstance(item, dict) and item.get("schemeKey")]
        return Message(text="\n".join(lines))

    def build_catalog_versions(self) -> Message:
        payload = self._payload()
        return Message(
            text=json.dumps(
                {"issue": payload.get("issue_catalog_version"), "scheme": payload.get("scheme_catalog_version")},
                ensure_ascii=False,
            )
        )

    def build_case_id(self) -> Message:
        return Message(text=str(self._payload().get("case_id") or ""))

from __future__ import annotations

import json
import re

import httpx
from lfx.custom import Component
from lfx.io import DropdownInput, FloatInput, IntInput, MessageTextInput, MultilineInput, Output, StrInput
from lfx.schema.message import Message

_FENCE = re.compile(r"^\s*```(?:json)?\s*(.*?)\s*```\s*$", re.I | re.S)
MAX_SELECTED = 3


class IssueSelector(Component):
    display_name = "Issue Selector"
    description = (
        "Reads the whole judgment and automatically selects at most 3 distinct detailed issues from the 52-item "
        "issue catalog, each with a selection reason and a verbatim evidence quote. Validates the answer "
        "(at most 3, catalog IDs only, no duplicates) with limited retries. Zero is allowed with a reason."
    )
    icon = "ListChecks"
    name = "IssueSelector"

    inputs = [
        MessageTextInput(name="judgment", display_name="Judgment", required=True),
        MessageTextInput(name="issue_catalog", display_name="Issue Catalog (JSON lines)", required=True),
        MessageTextInput(name="claim_json", display_name="Main Claim JSON", required=True),
        MultilineInput(
            name="prompt_template",
            display_name="Selection Prompt Template",
            info="Variables: {max_issues}, {main_claim}, {issue_catalog}, {judgment}. Substituted literally.",
            value="",
        ),
        MultilineInput(name="system_message", display_name="System Message", value="", advanced=True),
        StrInput(name="base_url", display_name="Ollama Base URL", value="http://localhost:11434"),
        DropdownInput(
            name="model_name",
            display_name="Model Name",
            options=["gemma4:e4b-it-qat", "solar:10.7b", "qwen2.5:7b-instruct", "qwen2.5:14b-instruct"],
            value="gemma4:e4b-it-qat",
            combobox=True,
        ),
        FloatInput(name="temperature", display_name="Temperature", value=0.1),
        IntInput(name="num_ctx", display_name="Context Window Size", value=16384),
        IntInput(name="timeout", display_name="Timeout per call (s)", value=600, info="0 = no limit"),
        IntInput(name="retries", display_name="Retries on invalid answer", value=2, advanced=True),
    ]

    outputs = [Output(display_name="Selection JSON", name="selection_json", method="select")]

    # ---- helpers ----
    @staticmethod
    def _text(value) -> str:
        text = getattr(value, "text", None)
        return str(text if text is not None else (value or ""))

    @staticmethod
    def parse_json_object(text: str) -> dict:
        stripped = str(text or "").strip()
        match = _FENCE.match(stripped)
        if match:
            stripped = match.group(1).strip()
        value = json.loads(stripped, strict=False)
        if not isinstance(value, dict):
            raise ValueError("answer must be a JSON object")
        return value

    @staticmethod
    def catalog_ids(text: str) -> list[str]:
        ids = []
        for line in str(text or "").splitlines():
            line = line.strip()
            if not line:
                continue
            try:
                item = json.loads(line, strict=False)
            except ValueError:
                continue
            if isinstance(item, dict) and item.get("issue_id"):
                ids.append(str(item["issue_id"]))
        return ids

    @staticmethod
    def validate_selection(obj: dict, catalog: set[str]) -> tuple[list[dict], str, list[str]]:
        """(선택 목록, 0개 사유, 오류). 오류가 있으면 재시도 대상."""
        errors: list[str] = []
        items = obj.get("selected_issues")
        if not isinstance(items, list):
            return [], "", ["selected_issues must be an array"]
        if len(items) > MAX_SELECTED:
            errors.append(f"selected {len(items)} issues; at most {MAX_SELECTED} are allowed")
        selected: list[dict] = []
        seen: set[str] = set()
        for index, item in enumerate(items, start=1):
            if not isinstance(item, dict):
                errors.append(f"selected_issues[{index}] must be an object")
                continue
            issue_id = str(item.get("issue_id") or "").strip()
            if issue_id not in catalog:
                errors.append(f"selected_issues[{index}].issue_id {issue_id!r} is not in the issue catalog")
                continue
            if issue_id in seen:
                errors.append(f"issue_id {issue_id} is selected more than once")
                continue
            seen.add(issue_id)
            issue_text = str(item.get("issue_text") or "").strip()
            reason = str(item.get("selection_reason") or "").strip()
            if not issue_text:
                errors.append(f"selected_issues[{index}].issue_text is empty")
            if not reason:
                errors.append(f"selected_issues[{index}].selection_reason is empty")
            selected.append(
                {
                    "issue_id": issue_id,
                    "issue_text": issue_text,
                    "selection_reason": reason,
                    "evidence_quote": str(item.get("evidence_quote") or "").strip(),
                }
            )
        no_issue_reason = str(obj.get("no_issue_reason") or "").strip()
        if not items and not no_issue_reason:
            errors.append("no issue selected but no_issue_reason is empty")
        return selected, no_issue_reason, errors

    def render_prompt(self, template: str, main_claim: str, catalog: str, judgment: str) -> str:
        rendered = template.replace("{max_issues}", str(MAX_SELECTED)).replace("{main_claim}", main_claim)
        rendered = rendered.replace("{issue_catalog}", catalog)
        # 판결문은 마지막에 넣어 원문 안의 중괄호가 변수로 오인되지 않게 한다.
        return rendered.replace("{judgment}", judgment)

    def call_model(self, messages: list[dict]) -> dict:
        payload = {
            "model": self._text(self.model_name),
            "messages": messages,
            "format": "json",
            "stream": False,
            "options": {"temperature": float(self.temperature or 0), "num_ctx": int(self.num_ctx or 2048)},
        }
        timeout = int(self.timeout or 0)
        response = httpx.post(
            f"{self._text(self.base_url).rstrip('/')}/api/chat",
            json=payload,
            timeout=None if timeout <= 0 else float(timeout),
        )
        if response.status_code >= 400:
            raise RuntimeError(f"Ollama HTTP {response.status_code}: {response.text[:300]}")
        body = response.json()
        return {
            "content": (body.get("message") or {}).get("content") or "",
            "prompt_eval_count": body.get("prompt_eval_count"),
            "done_reason": body.get("done_reason"),
        }

    def select(self) -> Message:
        catalog_text = self._text(self.issue_catalog)
        catalog = set(self.catalog_ids(catalog_text))
        if not catalog:
            raise ValueError("Issue catalog is empty; the relay server must send the 52-item catalog.")
        template = self._text(self.prompt_template)
        if not template.strip():
            raise ValueError("Selection Prompt Template is empty.")
        try:
            main_claim = str(self.parse_json_object(self._text(self.claim_json)).get("main_claim") or "").strip()
        except ValueError:
            main_claim = ""
        prompt = self.render_prompt(template, main_claim, catalog_text, self._text(self.judgment))
        messages = []
        system = self._text(getattr(self, "system_message", ""))
        if system.strip():
            messages.append({"role": "system", "content": system})
        messages.append({"role": "user", "content": prompt})

        attempts = max(1, int(self.retries or 0) + 1)
        errors: list[str] = []
        warnings: list[str] = []
        for attempt in range(1, attempts + 1):
            try:
                result = self.call_model(messages)
            except Exception as error:  # noqa: BLE001 - 호출 오류도 기록하고 재시도한다.
                errors = [f"attempt {attempt}: {error.__class__.__name__}: {error}"]
                continue
            content = result.get("content", "")
            used = result.get("prompt_eval_count")
            num_ctx = int(self.num_ctx or 0)
            if isinstance(used, int) and num_ctx and used >= num_ctx - 8:
                warnings.append(f"context_limit: prompt used {used} of {num_ctx} tokens; the judgment may have been truncated.")
            try:
                obj = self.parse_json_object(content)
            except ValueError as error:
                errors = [f"attempt {attempt}: invalid JSON: {error}"]
            else:
                selected, reason, errors = self.validate_selection(obj, catalog)
                if not errors:
                    status = "ok" if selected else "no_issues"
                    self.status = f"{status}: {', '.join(i['issue_id'] for i in selected) or reason}"
                    return Message(
                        text=json.dumps(
                            {
                                "status": status,
                                "selected": selected,
                                "no_issue_reason": reason,
                                "attempts": attempt,
                                "warnings": sorted(set(warnings)),
                                "model": self._text(self.model_name),
                            },
                            ensure_ascii=False,
                        )
                    )
            # 제한된 재시도: 무엇이 틀렸는지 알려 주고 다시 답하게 한다.
            messages = [
                *messages,
                {"role": "assistant", "content": content},
                {
                    "role": "user",
                    "content": "Your previous answer was invalid:\n- "
                    + "\n- ".join(errors)
                    + f"\nReturn corrected JSON only. Select at most {MAX_SELECTED} distinct issue_id values from the catalog.",
                },
            ]
        self.status = "invalid selection"
        return Message(
            text=json.dumps(
                {"status": "invalid", "selected": [], "no_issue_reason": "", "attempts": attempts, "errors": errors, "warnings": sorted(set(warnings))},
                ensure_ascii=False,
            )
        )

from __future__ import annotations

import json
import re
import time

import httpx
from lfx.custom import Component
from lfx.io import DropdownInput, FloatInput, IntInput, MessageTextInput, MultilineInput, Output, StrInput
from lfx.schema.message import Message

_FENCE = re.compile(r"^\s*```(?:json)?\s*(.*?)\s*```\s*$", re.I | re.S)
MAX_SELECTED = 3


class BranchError(ValueError):
    pass


class IssueBranchExtractor(Component):
    display_name = "Issue Branch Extractor"
    description = (
        "For each selected issue (at most 3) calls Ollama once to extract the upper/lower I-node texts with "
        "verbatim evidence quotes. Summaries and Walton schemes are produced by later stages. Per-issue failures "
        "and context-limit warnings are reported instead of being dropped."
    )
    icon = "GitBranch"
    name = "IssueBranchExtractor"

    inputs = [
        MessageTextInput(name="selection_json", display_name="Selection JSON", required=True),
        MessageTextInput(name="judgment", display_name="Judgment", required=True),
        MessageTextInput(name="claim_json", display_name="Main Claim JSON", required=True),
        MultilineInput(
            name="prompt_template",
            display_name="Branch Prompt Template",
            info="Variables: {issue_json}, {main_claim}, {judgment}. Substituted literally (JSON braces are safe).",
            value="",
        ),
        MultilineInput(name="system_message", display_name="System Message", value="", advanced=True),
        StrInput(name="base_url", display_name="Ollama Base URL", value="http://localhost:11434"),
        DropdownInput(
            name="model_name",
            display_name="Model Name",
            options=["gemma4:e4b-it-qat", "solar:10.7b", "qwen2.5:7b-instruct", "qwen2.5:14b-instruct"],
            value="gemma4:e4b-it-qat",
            combobox=True,
        ),
        FloatInput(name="temperature", display_name="Temperature", value=0.1),
        IntInput(name="num_ctx", display_name="Context Window Size", value=16384),
        IntInput(name="timeout", display_name="Timeout per issue (s)", value=600, info="0 = no limit"),
        IntInput(name="retries", display_name="Retries on invalid JSON", value=1, advanced=True),
    ]

    outputs = [Output(display_name="Branches JSON", name="branches_json", method="extract")]

    # ---- parsing helpers (pure) ----
    @staticmethod
    def _text(value) -> str:
        text = getattr(value, "text", None)
        return str(text if text is not None else (value or ""))

    @staticmethod
    def parse_json_object(text: str, label: str) -> dict:
        stripped = str(text or "").strip()
        match = _FENCE.match(stripped)
        if match:
            stripped = match.group(1).strip()
        try:
            value = json.loads(stripped, strict=False)
        except ValueError as error:
            raise BranchError(f"{label} is not valid JSON: {error}") from error
        if not isinstance(value, dict):
            raise BranchError(f"{label} must be a JSON object.")
        return value

    @staticmethod
    def validate_branch(obj: dict) -> dict:
        upper = obj.get("upper_i_node")
        if isinstance(upper, str):
            upper = {"text": upper}
        if not isinstance(upper, dict) or not str(upper.get("text") or "").strip():
            raise BranchError("upper_i_node.text is missing.")
        lowers = obj.get("lower_i_nodes")
        if not isinstance(lowers, list) or not lowers:
            raise BranchError("lower_i_nodes must be a non-empty array.")
        normalized = []
        for index, lower in enumerate(lowers, start=1):
            if isinstance(lower, str):
                lower = {"text": lower}
            if not isinstance(lower, dict) or not str(lower.get("text") or "").strip():
                raise BranchError(f"lower_i_nodes[{index}].text is missing.")
            normalized.append({"text": str(lower["text"]).strip(), "evidence_quote": str(lower.get("evidence_quote") or "").strip()})
        return {
            "upper_i_node": {"text": str(upper["text"]).strip(), "evidence_quote": str(upper.get("evidence_quote") or "").strip()},
            "lower_i_nodes": normalized,
        }

    @staticmethod
    def render_prompt(template: str, issue: dict, main_claim: str, judgment: str) -> str:
        rendered = template.replace("{issue_json}", json.dumps(issue, ensure_ascii=False, indent=2))
        rendered = rendered.replace("{main_claim}", main_claim)
        # 판결문을 마지막에 넣어 원문 안의 중괄호가 다른 변수로 오인되지 않게 한다.
        return rendered.replace("{judgment}", judgment)

    # ---- model call ----
    def call_model(self, prompt: str) -> dict:
        messages = []
        system = self._text(getattr(self, "system_message", ""))
        if system.strip():
            messages.append({"role": "system", "content": system})
        messages.append({"role": "user", "content": prompt})
        payload = {
            "model": self._text(self.model_name),
            "messages": messages,
            "format": "json",
            "stream": False,
            "options": {"temperature": float(self.temperature or 0), "num_ctx": int(self.num_ctx or 2048)},
        }
        timeout = int(self.timeout or 0)
        response = httpx.post(
            f"{self._text(self.base_url).rstrip('/')}/api/chat",
            json=payload,
            timeout=None if timeout <= 0 else float(timeout),
        )
        if response.status_code >= 400:
            raise BranchError(f"Ollama HTTP {response.status_code}: {response.text[:300]}")
        body = response.json()
        return {
            "content": (body.get("message") or {}).get("content") or "",
            "prompt_eval_count": body.get("prompt_eval_count"),
            "done_reason": body.get("done_reason"),
        }

    def extract_one(self, index: int, issue: dict, main_claim: str, judgment: str, template: str) -> dict:
        prompt = self.render_prompt(
            template,
            {"issue_id": issue["issue_id"], "issue_text": issue["issue_text"], "selection_reason": issue["selection_reason"]},
            main_claim,
            judgment,
        )
        attempts = max(1, int(self.retries or 0) + 1)
        warnings: list[str] = []
        last_error = ""
        started = time.monotonic()
        for attempt in range(1, attempts + 1):
            try:
                result = self.call_model(prompt)
            except Exception as error:  # noqa: BLE001 - 쟁점별 오류로 기록한다.
                last_error = f"{error.__class__.__name__}: {error}"
                continue
            num_ctx = int(self.num_ctx or 0)
            used = result.get("prompt_eval_count")
            if isinstance(used, int) and num_ctx and used >= num_ctx - 8:
                warnings.append(f"context_limit: prompt used {used} of {num_ctx} tokens; the judgment may have been truncated.")
            if result.get("done_reason") == "length":
                warnings.append("output_truncated: the model stopped at the length limit.")
            try:
                branch = self.validate_branch(self.parse_json_object(result["content"], "branch output"))
            except BranchError as error:
                last_error = f"attempt {attempt}: {error}"
                continue
            return {
                "issue_id": issue["issue_id"],
                "issue_index": index,
                "status": "ok",
                "attempts": attempt,
                "seconds": round(time.monotonic() - started, 1),
                "warnings": sorted(set(warnings)),
                **branch,
            }
        return {
            "issue_id": issue["issue_id"],
            "issue_index": index,
            "status": "failed",
            "attempts": attempts,
            "seconds": round(time.monotonic() - started, 1),
            "error": last_error or "unknown error",
            "warnings": sorted(set(warnings)),
        }

    def extract(self) -> Message:
        selection = self.parse_json_object(self._text(self.selection_json), "Selection JSON")
        status = selection.get("status")
        selected = selection.get("selected") if isinstance(selection.get("selected"), list) else []
        if status != "ok":
            # 쟁점이 없거나 선택이 무효면 가지를 만들지 않는다(가짜 추출 금지).
            self.status = f"skipped: selection status {status}"
            return Message(text=json.dumps({"status": "skipped", "reason": f"selection status {status}", "branches": []}, ensure_ascii=False))
        if len(selected) > MAX_SELECTED:
            raise ValueError(f"Selection has {len(selected)} issues; at most {MAX_SELECTED} are allowed.")
        try:
            main_claim = str(self.parse_json_object(self._text(self.claim_json), "Main Claim JSON").get("main_claim") or "").strip()
        except BranchError:
            main_claim = ""
        template = self._text(self.prompt_template)
        if not template.strip():
            raise ValueError("Branch Prompt Template is empty.")
        judgment = self._text(self.judgment)
        branches = [self.extract_one(index, issue, main_claim, judgment, template) for index, issue in enumerate(selected, start=1)]
        summary = {
            "selected": len(selected),
            "ok": sum(1 for b in branches if b["status"] == "ok"),
            "failed": sum(1 for b in branches if b["status"] == "failed"),
        }
        self.status = f"{summary['ok']} ok / {summary['failed']} failed"
        return Message(text=json.dumps({"status": "done", "summary": summary, "branches": branches}, ensure_ascii=False))

